INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca65-701d-9d8a-47de94dacbed'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'Solve the compound inequality 4 - 3x < 2x + 9 < x + 15.', '-1 < x < 6', '4 - 3x < 2x + 9 => 5x > -5 => x > -1. 2x + 9 < x + 15 => x < 6. Combining gives -1 < x < 6.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.484Z'::timestamptz, '2026-08-15T07:50:40.484Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca6e-73ea-865b-a0a24f469cc1'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'The first four terms of a sequence are 3, 8, 15 and 24. Find an expression for the nth term and calculate the 10th term.', 'Tn = n² + 2n; T10 = 120', 'Differences are 5, 7, 9 (second difference = 2). Formula is Tn = n² + 2n. For n = 10, T10 = 10² + 2(10) = 120.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.494Z'::timestamptz, '2026-08-15T07:50:40.494Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca78-7f94-aa0b-a72a6e5d89e6'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'Solve the inequality 7 - 4x ≤ 2x + 19 and state the least integer solution.', 'x ≥ -2; least integer = -2', '7 - 4x ≤ 2x + 19 => -6x ≤ 12 => x ≥ -2. The least integer is -2.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.504Z'::timestamptz, '2026-08-15T07:50:40.504Z'::timestamptz) ON CONFLICT (id) DO NOTHING;